// Slot and ring sketch (conceptual)
typedef struct alignas(256) Slot {
  uint64_t seq;
  uint8_t payload[256];
} Slot;

typedef struct {
  Slot *slots;
  _Atomic uint32_t head, tail;
} Ring;

bool ring_push(Ring *r, const void *src){
  uint32_t h = atomic_load_explicit(&r->head, memory_order_relaxed);
  Slot *s = &r->slots[h & (N-1)];
  uint64_t seq = atomic_load_explicit(&s->seq, memory_order_acquire);
  if (seq != h) return false; // full
  // non-temporal payload write path placeholder
  memcpy(s->payload, src, 256);
  atomic_store_explicit(&s->seq, h+1, memory_order_release);
  atomic_store_explicit(&r->head, h+1, memory_order_relaxed);
  return true;
}
```

